Sdb* process_version_definitions(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    void* data = elf_getdata(bin, shdr);
    if (!data) {
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    const char* strtab = elf_strptr(bin, shdr->sh_link, 0);
    if (!strtab) {
        sdb_free(sdb);
        return NULL;
    }

    const Elf_(Word) num_entries = sz / shdr->sh_entsize;
    for (Elf_(Word) i = 0; i < num_entries; i++) {
        const Elf_(Half) version = ((Elf_(Half)*)data)[i];
        if (version == 0) {
            break;
        }

        const char* name = &strtab[i];
        if (!name) {
            sdb_free(sdb);
            return NULL;
        }

        if (sdb_set(sdb, name, version, 0) < 0) {
            sdb_free(sdb);
            return NULL;
        }
    }

    return sdb;
}

Sdb* process_version_definitions(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    if (!shdr || !bin) {
        return NULL;
    }

    Elf_(Shdr)* symtab = NULL;
    Elf_(Word) link = shdr->sh_link;
    if (link < bin->shnum && link < bin->shnum) {
        symtab = bin->shdr + link;
    }

    char* strtab = NULL;
    if (symtab) {
        Elf_(Word) strndx = symtab->sh_link;
        if (strndx < bin->shnum) {
            Elf_(Shdr)* strsec = bin->shdr + strndx;
            if (strsec->sh_type == SHT_STRTAB) {
                strtab = bin->strbuf + strsec->sh_offset;
            }
        }
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    uint8_t* data = (uint8_t*)shdr->sh_addr;
    size_t num = sz / sizeof(Elf_(Verdef));
    for (size_t i = 0; i < num; ++i) {
        Elf_(Verdef)* verdef = (Elf_(Verdef*)(data + i * sizeof(Elf_(Verdef)));
        if (!verdef || verdef->vd_ndx == 0) {
            continue;
        }

        char key[64];
        snprintf(key, sizeof(key), "verdef.%d", verdef->vd_ndx);

        Elf_(Verdaux)* verdaux = (Elf_(Verdaux*)((uint8_t*)verdef + sizeof(Elf_(Verdef)));
        for (int j = 0; j < verdef->vd_cnt; ++j) {
            sdb_num_put(sdb, key, (ut64)verdaux->vda_name);
            sdb_set(sdb, key, verdaux->vda_name, 0);
            verdaux = (Elf_(Verdaux*)((uint8_t*)verdaux + sizeof(Elf_(Verdaux)) + verdaux->vda_name));
        }
    }

    if (sdb->kv.n > 0) {
        return sdb;
    }

    sdb_free(sdb);
    return NULL;
}

Sdb* process_version_definitions(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    uint8_t *data = (uint8_t*)malloc(sz);
    if (!data) {
        return NULL;
    }

    if (elf_read_section(bin, shdr, data, sz) != sz) {
        free(data);
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        free(data);
        return NULL;
    }

    uint64_t offset = 0;
    while (offset < sz) {
        Elf_(Half) vd_version = *(Elf_(Half)*)(data + offset);
        Elf_(Word) vd_flags = *(Elf_(Word)*)(data + offset + 2);
        Elf_(Word) vd_ndx = *(Elf_(Word)*)(data + offset + 6);
        Elf_(Xword) vd_hash = *(Elf_(Xword)*)(data + offset + 8);
        Elf_(Xword) vd_aux = *(Elf_(Xword)*)(data + offset + 16);
        Elf_(Xword) vd_next = *(Elf_(Xword)*)(data + offset + 24);

        char *name = (char*)(data + offset + 24 + vd_aux);
        char key[256];
        snprintf(key, sizeof(key), "version.%s", name);

        if (sdb_set(sdb, key, "1", 0) != 0) {
            sdb_free(sdb);
            free(data);
            return NULL;
        }

        offset += vd_next;
    }

    free(data);
    return sdb;
}

Sdb* process_elf_version_definitions(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    char* strtab = NULL;
    if (shdr->sh_link > 0) {
        Elf_(Shdr)* link_shdr = bin->shdr + shdr->sh_link;
        strtab = (char*) bin->shdr_str + link_shdr->sh_offset;
    }

    char* data = (char*) shdr->sh_offset + bin->buf;
    size_t offset = 0;

    while (offset < sz) {
        Elf_(Half) vda = *(Elf_(Half)*)(data + offset);
        offset += sizeof(Elf_(Half));
        if (vda == 0) {
            break;
        }

        if (vda != 1) {
            continue;
        }

        Elf_(Word) ndx = *(Elf_(Word)*)(data + offset);
        offset += sizeof(Elf_(Word));
        Elf_(Word) num = *(Elf_(Word)*)(data + offset);
        offset += sizeof(Elf_(Word));
        Elf_(Word) len = *(Elf_(Word)*)(data + offset);
        offset += sizeof(Elf_(Word));

        char* name = strtab + *(Elf_(Word)*)(data + offset);
        offset += sizeof(Elf_(Word));
        if (!name) {
            sdb_free(sdb);
            return NULL;
        }

        char key[256];
        snprintf(key, sizeof(key), "version.%s", name);

        if (sdb_set(sdb, key, "1", 0) < 0) {
            sdb_free(sdb);
            return NULL;
        }

        for (int i = 0; i < num; ++i) {
            Elf_(Word) aux_len = *(Elf_(Word)*)(data + offset);
            offset += sizeof(Elf_(Word));
            Elf_(Word) aux_ndx = *(Elf_(Word)*)(data + offset);
            offset += sizeof(Elf_(Word));
            Elf_(Word) aux_flags = *(Elf_(Word)*)(data + offset);
            offset += sizeof(Elf_(Word));
            Elf_(Word) aux_other = *(Elf_(Word)*)(data + offset);
            offset += sizeof(Elf_(Word));
            Elf_(Word) aux_name = *(Elf_(Word)*)(data + offset);
            offset += sizeof(Elf_(Word));

            char* aux_name_str = strtab + aux_name;
            if (!aux_name_str) {
                sdb_free(sdb);
                return NULL;
            }

            char aux_key[512];
            snprintf(aux_key, sizeof(aux_key), "version.%s.%s", name, aux_name_str);

            char aux_value[16];
            snprintf(aux_value, sizeof(aux_value), "%d", aux_flags);

            if (sdb_set(sdb, aux_key, aux_value, 0) < 0) {
                sdb_free(sdb);
                return NULL;
            }
        }
    }

    if (offset != sz) {
        sdb_free(sdb);
        return NULL;
    }

    return sdb;
}

#include <stdlib.h>
#include <string.h>

Sdb* process_version_definitions(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    // Allocate memory for version definitions
    void *data = malloc(sz);
    if (!data) {
        return NULL;
    }

    // Retrieve section names and initialize Sdb
    Sdb *sdb = sdb_new0();
    if (!sdb) {
        free(data);
        return NULL;
    }

    // Iterate through version definitions
    // (Implementation assumes helper functions like get_version_attributes exist)
    int offset = 0;
    while (offset < sz) {
        VersionDef *def = (VersionDef *)((char*)data + offset);
        if (!def || def->length <= 0) {
            break;
        }

        char *version_name = get_version_name(def);
        if (!version_name) {
            break;
        }

        if (!sdb_set(sdb, version_name, def->value, 0)) {
            break;
        }

        // Process auxiliary entries
        int aux_offset = offset + sizeof(VersionDef);
        while (aux_offset < sz) {
            VersionAux *aux = (VersionAux *)((char*)data + aux_offset);
            if (!aux || aux->length <= 0) {
                break;
            }

            char *aux_name = get_version_aux_name(aux);
            if (!aux_name || !sdb_set(sdb, aux_name, aux->value, 0)) {
                break;
            }

            aux_offset += aux->length;
        }

        offset += def->length;
    }

    free(data);
    return sdb;
}
